export const vocabulary = [
  [4,'Law of constant composition','A pure compound always has the same elements in the same proportions by mass. Also called the law of definite proportions.'],
  [4,'Law of conservation of mass','In an ordinary chemical reaction in a closed system, total mass stays constant: atoms are rearranged, not created or destroyed.'],
  [4,'Law of multiple proportions','When two elements form more than one compound, the masses of one that combine with a fixed mass of the other are in small whole-number ratios. CO and CO₂ give a 1:2 oxygen-mass ratio.'],
  [4,"Dalton’s atomic theory",'Matter consists of atoms; atoms combine in whole-number ratios and rearrange in chemical reactions. His claims that atoms are indivisible and all atoms of an element have identical masses were later revised.'],
  [4,'Nuclear atom','An atom with a tiny, dense, positively charged nucleus, electrons outside it, and mostly empty space.'],
  [4,'Nucleus','The small, dense center of an atom containing protons and neutrons (ordinary hydrogen-1 has no neutron). It contains nearly all atomic mass.'],
  [4,'Proton','A particle in the nucleus with a +1 charge and a mass of about 1 amu.'],
  [4,'Neutron','A particle in the nucleus with no charge and a mass of about 1 amu.'],
  [4,'Electron','A particle outside the nucleus with a −1 charge and a mass of about 1/1836 amu.'],
  [4,'Atomic number (Z)','The number of protons. It uniquely identifies an element.'],
  [4,'Mass number (A)','The whole-number total of protons and neutrons in a specific isotope.'],
  [4,'Isotopes','Atoms of the same element with the same number of protons but different numbers of neutrons and different mass numbers.'],
  [4,'Average atomic mass','The weighted average of the masses of an element’s naturally occurring isotopes, using their fractional abundances.'],
  [4,'Ion','An atom or group of atoms with a net electric charge from losing or gaining electrons.'],
  [4,'Cation / Anion','A cation is positive (electron loss); an anion is negative (electron gain).'],
  [4,'Group (family) / Period','A group is a vertical column; a period is a horizontal row of the periodic table. Main-group elements in a group have similar valence-electron patterns.'],
  [5,'Compound','A pure substance made of two or more different elements chemically combined in a fixed ratio.'],
  [5,'Chemical formula','Symbols and subscripts that give the elements and their relative numbers. Ionic formulas give the simplest ratio of ions; molecular formulas give actual atom counts per molecule.'],
  [5,'Ionic compound','A neutral combination of cations and anions held together by electrostatic attraction, often a metal plus a nonmetal or a compound containing polyatomic ions.'],
  [5,'Covalent (molecular) compound','A compound whose atoms share electrons, usually nonmetals. In this worksheet, use prefix naming for binary molecular compounds.'],
  [5,'Polyatomic ion','A bonded group of atoms with an overall charge, such as SO₄²⁻ or NH₄⁺. Keep the group intact when writing formulas.'],
  [5,'Transition metal','An element in the central d-block of the periodic table in the classroom classification. Many have more than one common ion charge.'],
  [5,'Roman numeral (Stock system)','A numeral that states the metal’s charge in an ionic name, not the number of metal atoms. Iron(III) means Fe³⁺.'],
  [5,'Acid','A substance that donates H⁺; in water, H⁺ is associated with water as H₃O⁺. Use acid names for the aqueous acids in this guide.'],
  [5,'Diatomic elements','The seven elements commonly written as two-atom molecules in their elemental form: H₂, N₂, O₂, F₂, Cl₂, Br₂, I₂. This rule does not change subscripts inside compounds.'],
  [5,'Metalloid','An element with properties between metals and nonmetals, near the staircase: B, Si, Ge, As, Sb, and Te are common classroom examples.']
];

